@Test
void getFromFuture() throws Exception {
    runInThread(() -> {
        CompletableFuture completableFuture = mock(CompletableFuture.class, RETURNS_DEEP_STUBS);
        when(completableFuture.get(any(long.class), any(TimeUnit.class))).thenReturn(new Object());
        Object fromFuture = SUT.getFromFuture(completableFuture, 1);
        assertNotNull(fromFuture);
    });
    runInThread(() -> {
        CompletableFuture completableFuture = mock(CompletableFuture.class, RETURNS_DEEP_STUBS);
        when(completableFuture.get(anyLong(), any())).thenThrow(InterruptedException.class);
        assertThrows(PlcRuntimeException.class, () -> SUT.getFromFuture(completableFuture, 1));
    });
    runInThread(() -> {
        CompletableFuture completableFuture = mock(CompletableFuture.class, RETURNS_DEEP_STUBS);
        when(completableFuture.get(anyLong(), any())).thenThrow(ExecutionException.class);
        assertThrows(PlcRuntimeException.class, () -> SUT.getFromFuture(completableFuture, 1));
    });
    runInThread(() -> {
        CompletableFuture completableFuture = mock(CompletableFuture.class, RETURNS_DEEP_STUBS);
        when(completableFuture.get(anyLong(), any())).thenThrow(TimeoutException.class);
        assertThrows(PlcRuntimeException.class, () -> SUT.getFromFuture(completableFuture, 1));
    });
    assertFalse("The current Thread should not be interrupted", Thread.currentThread().isInterrupted());
}

@Test
public void adsTcpPlcConnectionOf() throws Exception {
    {
        assertThrows(NullPointerException.class, () -> SUT.adsTcpPlcConnectionOf(null, null, null, null, null, null));
        assertThrows(NullPointerException.class, () -> SUT.adsTcpPlcConnectionOf(inetAddress, null, null, null, null, null));
        assertThrows(NullPointerException.class, () -> SUT.adsTcpPlcConnectionOf(inetAddress, null, targetAmsNetId, null, null, null));
    }
    {
        AdsTcpPlcConnection adsTcpPlcConnection = SUT.adsTcpPlcConnectionOf(inetAddress, null, targetAmsNetId, targetAmsPort, null, null);
        assertEquals(inetAddress, adsTcpPlcConnection.getRemoteAddress());
        assertEquals(targetAmsNetId, adsTcpPlcConnection.getTargetAmsNetId());
        assertEquals(targetAmsPort, adsTcpPlcConnection.getTargetAmsPort());
