/**
 * This test handles the special case in which a response is part of a single request message.
 * This means that it is immediately finished and is hereby immediately processed.
 *
 * @throws PlcException
 */
@Test
public void processCompositeMessageReadResponse() throws PlcException {
    S7RequestMessage originalRequestMessage = new S7RequestMessage(MessageType.JOB, (short) 1, Collections.singletonList(new VarParameter(ParameterType.READ_VAR, Arrays.asList(new S7AnyVarParameterItem(SpecificationType.VARIABLE_SPECIFICATION, MemoryArea.DATA_BLOCKS, TransportSize.BYTE, (short) 1, (short) 1, (short) 2, (byte) 0), new S7AnyVarParameterItem(SpecificationType.VARIABLE_SPECIFICATION, MemoryArea.DATA_BLOCKS, TransportSize.BYTE, (short) 1, (short) 3, (short) 4, (byte) 0)))), Collections.emptyList(), null);
    DefaultS7MessageProcessor.S7CompositeRequestMessage compositeRequestMessage = new DefaultS7MessageProcessor.S7CompositeRequestMessage(originalRequestMessage);
    S7RequestMessage fragment1RequestMessage = new S7RequestMessage(MessageType.JOB, (short) 1, Collections.singletonList(new VarParameter(ParameterType.READ_VAR, Arrays.asList(new S7AnyVarParameterItem(SpecificationType.VARIABLE_SPECIFICATION, MemoryArea.DATA_BLOCKS, TransportSize.BYTE, (short) 1, (short) 1, (short) 2, (byte) 0)))), Collections.emptyList(), compositeRequestMessage);
    compositeRequestMessage.addRequestMessage(fragment1RequestMessage);
    S7RequestMessage fragment2RequestMessage = new S7RequestMessage(MessageType.JOB, (short) 3, Collections.singletonList(new VarParameter(ParameterType.READ_VAR, Arrays.asList(new S7AnyVarParameterItem(SpecificationType.VARIABLE_SPECIFICATION, MemoryArea.DATA_BLOCKS, TransportSize.BYTE, (short) 1, (short) 3, (short) 4, (byte) 0)))), Collections.emptyList(), compositeRequestMessage);
    compositeRequestMessage.addRequestMessage(fragment2RequestMessage);
    // Virtually add a response for the first response.
    fragment1RequestMessage.setAcknowledged(true);
    S7ResponseMessage fragment1ResponseMessage = new S7ResponseMessage(MessageType.JOB, (short) 2, Collections.singletonList(new VarParameter(ParameterType.READ_VAR, new LinkedList<>(Collections.singletonList(new S7AnyVarParameterItem(SpecificationType.VARIABLE_SPECIFICATION, MemoryArea.DATA_BLOCKS, TransportSize.BYTE, (short) 1, (short) 1, (short) 2, (byte) 0))))), Collections.singletonList(new VarPayload(ParameterType.READ_VAR, new LinkedList<>(Collections.singletonList(new VarPayloadItem(DataTransportErrorCode.OK, DataTransportSize.BYTE_WORD_DWORD, new byte[] { 0x42 }))))), (byte) 0x00, (byte) 0x00);
    S7ResponseMessage processedResponse = SUT.processResponse(fragment1RequestMessage, fragment1ResponseMessage);
    // As only one of the two requests is responded, the result should be null.
    assertThat(processedResponse, nullValue());
    // Virtually add a response for the second response.
    fragment2RequestMessage.setAcknowledged(true);
    S7ResponseMessage fragment2ResponseMessage = new S7ResponseMessage(MessageType.JOB, (short) 3, Collections.singletonList(new VarParameter(ParameterType.READ_VAR, new LinkedList<>(Collections.singletonList(new S7AnyVarParameterItem(SpecificationType.VARIABLE_SPECIFICATION, MemoryArea.DATA_BLOCKS, TransportSize.BYTE, (short) 1, (short) 3, (short) 4, (byte) 0))))), Collections.singletonList(new VarPayload(ParameterType.READ_VAR, new LinkedList<>(Collections.singletonList(new VarPayloadItem(DataTransportErrorCode.OK, DataTransportSize.BYTE_WORD_DWORD, new byte[] { 0x23 }))))), (byte) 0x00, (byte) 0x00);
    // This time we expect all messages of the composite to be acknowledged and the processResponse should
    // return a merged version of the individual responses content.
    processedResponse = SUT.processResponse(fragment2RequestMessage, fragment2ResponseMessage);
    // As this is the last request being responded, the result should be not null this time.
    assertThat(processedResponse, notNullValue());
    // Check the content.
    assertThat(processedResponse.getParameters(), hasSize(1));
    assertThat(processedResponse.getParameter(VarParameter.class).isPresent(), is(true));
    VarParameter varParameter = processedResponse.getParameter(VarParameter.class).get();
    assertThat(varParameter.getItems(), hasSize(2));
    assertThat(processedResponse.getPayloads(), hasSize(1));
    assertThat(processedResponse.getPayload(VarPayload.class).isPresent(), is(true));
    VarPayload varPayload = processedResponse.getPayload(VarPayload.class).get();
    assertThat(varPayload.getItems(), hasSize(2));
}

