@Test
@Ignore("Need to make tests run in Docker container first as this test requires libpcap or the entrie application to be run as 'root'")
@RequirePcap
public void testPingPacket() throws Exception {
    // Protocol number 1 = ICMP (Ping)
    RawIpSocket rawIpSocket = new RawIpSocket(1);
    CompletableFuture<Boolean> result = new CompletableFuture<>();
    // Simply print the result to the console
    rawIpSocket.addListener(rawData -> {
        System.out.println("Got response:");
        System.out.println(Arrays.toString(rawData));
        result.complete(true);
    });
    // Connect to the remote address
    // This doesn't really connect in the usual sense, it
    // does the ARP MAC address lookup and sets up the listener
    // to accept packets sent from that mac address to the
    // current machines with the given IP protocol id.
    // In this test we simply look for a real network device
    // (The loopback device doesn't have a MAC address)
    // and ping itself.
    for (PcapNetworkInterface dev : Pcaps.findAllDevs()) {
        System.out.println("Trying to read on device " + dev);
        if (!dev.getLinkLayerAddresses().isEmpty()) {
            for (PcapAddress pcapAddress : dev.getAddresses()) {
                if (pcapAddress.getAddress() instanceof Inet4Address) {
                    System.out.println("Trying to connect on PcapAddress " + pcapAddress);
                    rawIpSocket.connect("plc4x.apache.org");
                }
            }
        }
    }
    // On travis we won't have any interface at all so we don't need to run there
    assumeThat(rawIpSocket, notNullValue());
    // Simple ICMP (Ping packet)
    byte[] rawData = new byte[] { // Type (ICMP Ping Request) & Code (just 0)
    (byte) 0x08, (byte) 0x00, // Checksum
    (byte) 0xe3, (byte) 0xe5, // Identifier
    (byte) 0x00, (byte) 0x01, // Sequence Number
    (byte) 0x00, (byte) 0x00, // Payload (Just random data that was used to fit to the checksum)
    (byte) 0x00, (byte) 0x01, (byte) 0x02, (byte) 0x03, (byte) 0x04, (byte) 0x05, (byte) 0x06, (byte) 0x07, (byte) 0x08, (byte) 0x09 };
    // Write the raw packet to the remote host.
    rawIpSocket.write(rawData);
    try {
        result.get(3, TimeUnit.SECONDS);
    } catch (TimeoutException e) {
        fail("Request timed out.");
    }
}

@Test
public void doConnect() throws Exception {
    Channel channel = null;
    final EventLoopGroup workerGroup = new OioEventLoopGroup();
    try {
        Bootstrap bootstrap = new Bootstrap();
        bootstrap.group(workerGroup);
        bootstrap.channel(RawSocketChannel.class);
        // TODO we should use an explicit (configurable?) timeout here
        // bootstrap.option(ChannelOption.CONNECT_TIMEOUT_MILLIS, 1000);
        bootstrap.handler(new ChannelInitializer<RawSocketChannel>() {

            @Override
            protected void initChannel(RawSocketChannel ch) throws Exception {
                System.out.println("Initialize Buffer!");
                ch.pipeline().addLast(new ChannelInboundHandlerAdapter() {

                    @Override
                    public void channelRead(ChannelHandlerContext ctx, Object msg) throws Exception {
                        System.out.println(ByteBufUtil.prettyHexDump(((ByteBuf) msg)));
                    }
                });
                ch.pipeline().addLast(new ChannelHandlerAdapter() {

                    @Override
                    public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {
                        cause.printStackTrace();
                    }
                });
            }
        });
        // Start the client.
        PcapNetworkInterface loopbackDevice = Pcaps.findAllDevs().stream().filter(PcapNetworkInterface::isLoopBack).findFirst().orElse(null);
        Assert.assertNotNull("Couldn't find loopback device", loopbackDevice);
        final ChannelFuture f = bootstrap.connect(new RawSocketIpAddress(loopbackDevice.getName(), RawSocketAddress.ALL_PROTOCOLS, InetAddress.getByName("127.0.0.1"), 1234));
        // Wait for sync
        f.sync();
        // Wait till the session is finished initializing.
        channel = f.channel();
        System.out.println("Channel is connected and ready to use...");
        channel.writeAndFlush(Unpooled.wrappedBuffer("Hallo".getBytes()));
        // Prepare something to read
        Thread.sleep(10_000);
    } finally {
        if (channel != null) {
            channel.close().sync();
        }
        workerGroup.shutdownGracefully().sync();
    }
}

